import AppKit
import XCTest

@testable import Workroom

/// Multi-window foundations (issue #70): windows share one `ProjectStore` but keep independent
/// per-window `AppStore` state, and `WindowRegistry` tracks windows + aggregates their unread counts.
@MainActor
final class MultiWindowTests: XCTestCase {
  private func project(_ path: String, workrooms: [String] = []) -> Project {
    Project(
      path: path, vcs: "jj",
      workrooms: workrooms.map {
        Workroom(name: $0, path: "\(path)/\($0)", vcsName: "jj", warnings: [])
      }
    )
  }

  private func notification(_ targetID: String) -> WorkroomNotification {
    WorkroomNotification(
      id: UUID(), targetID: targetID, tabID: UUID(), kind: .osc, source: "src",
      title: "t", body: nil, date: Date(timeIntervalSince1970: 0), count: 1)
  }

  // MARK: ProjectStore sharing

  func testWindowsShareProjectsButNotSelection() {
    let shared = ProjectStore()
    let a = AppStore(projectStore: shared)
    let b = AppStore(projectStore: shared)

    shared.projects = [project("/p", workrooms: ["w"])]
    XCTAssertEqual(a.projects.map(\.id), ["/p"])
    XCTAssertEqual(b.projects.map(\.id), ["/p"], "both windows read the one shared project list")

    a.selectedTargetID = .root(project: "/p")
    XCTAssertEqual(a.selectedTargetID, .root(project: "/p"))
    XCTAssertNil(b.selectedTargetID, "selection is per-window, not shared")
  }

  func testProxyWritesThroughToSharedStore() {
    let shared = ProjectStore()
    let a = AppStore(projectStore: shared)
    let b = AppStore(projectStore: shared)

    a.projects = [project("/x")]
    XCTAssertEqual(
      shared.projects.map(\.id), ["/x"], "writing via one window updates the shared store")
    XCTAssertEqual(b.projects.map(\.id), ["/x"], "…and is visible to the other window")
  }

  func testIsolatedStoresDoNotShareProjects() {
    let a = AppStore()  // default: its own fresh ProjectStore
    let b = AppStore()
    a.projects = [project("/only-a")]
    XCTAssertTrue(
      b.projects.isEmpty, "bare AppStore() is isolated, so tests never pollute each other")
  }

  // MARK: Blank new windows

  func testInitialRestoreIsOneShot() {
    let shared = ProjectStore()
    XCTAssertTrue(
      shared.consumeInitialRestore(), "the first restoring window claims the saved selection")
    XCTAssertFalse(shared.consumeInitialRestore(), "every later window (incl. ⌘N) starts blank")
    XCTAssertFalse(shared.consumeInitialRestore())
  }

  // MARK: WindowRegistry

  func testRegistryTracksWindowsAndRoutesByWindow() {
    let registry = WindowRegistry()
    let shared = ProjectStore()
    let a = AppStore(projectStore: shared)
    let b = AppStore(projectStore: shared)
    let winA = NSWindow()
    let winB = NSWindow()

    registry.register(window: winA, store: a)

// MARK: Investigate (issue #146)

private func investigateBanner(_ target: TerminalTarget) -> AgentBannerState {
  .awaitingDiagnose(
    FailedCommand(
      command: "npm test", cwd: target.path, exitCode: 1, shell: nil, output: "",
      isRunTab: false, isRemote: false))
}

func testStartInvestigateBuildsCommandAndTracksTab() {
  let store = makeStore([project("/a", workrooms: ["main"])])
  let t = target(store, "/a", "main")
  let bannerState = investigateBanner(t)

  let tab = store.startInvestigate(bannerState: bannerState, target: t, cwd: t.path)

  XCTAssertEqual(captured.last, AgentPrompt.investigateCommandLine(for: bannerState))
  XCTAssertEqual(store.investigateTabs[tab.id], t.id)
}

func testInvestigateLivenessClearsViaChildExitAndViaTabRemoval() {
  let store = makeStore([project("/a", workrooms: ["main"])])
  let t = target(store, "/a", "main")
  let bannerState = investigateBanner(t)
  XCTAssertFalse(store.hasLiveRunCommand)

  let tab1 = store.startInvestigate(bannerState: bannerState, target: t, cwd: t.path)
  let surface1 = try! XCTUnwrap(tab1.surface)
  surface1.liveProcessOverrideForTesting = true
  XCTAssertTrue(store.hasLiveRunCommand)

  // Cleanup path 1: the process exits (`onChildExited`) — independent of the tab closing.
  surface1.handleChildExited(exitCode: 0)
  XCTAssertNil(store.investigateTabs[tab1.id])
  XCTAssertFalse(store.hasLiveRunCommand)

  // Cleanup path 2: the tab is closed/reaped (`onTabsRemoved`) — independent of `onChildExited`
  // ever firing (it isn't guaranteed to, per libghostty exit-reporting flakiness).
  let tab2 = store.startInvestigate(bannerState: bannerState, target: t, cwd: t.path)
  let surface2 = try! XCTUnwrap(tab2.surface)
  surface2.liveProcessOverrideForTesting = true
  XCTAssertTrue(store.hasLiveRunCommand)

  store.terminals.closeTab(tab2.id, for: t)
  XCTAssertNil(store.investigateTabs[tab2.id])
  XCTAssertFalse(store.hasLiveRunCommand)
}

func testGracefullyStopAllCompletesImmediatelyWithOnlyInvestigateTabLive() {
  let store = makeStore([project("/a", workrooms: ["main"])])
  let t = target(store, "/a", "main")
  let tab = store.startInvestigate(bannerState: investigateBanner(t), target: t, cwd: t.path)
  let surface = try! XCTUnwrap(tab.surface)
  surface.liveProcessOverrideForTesting = true
  XCTAssertTrue(store.hasLiveRunCommand)

  // `runStates` is empty — an Investigate-only session has no supervisor to SIGTERM, so this must
  // resolve immediately rather than wait on a `runStates` entry that will never appear (issue #146).
  var completed = false
  store.gracefullyStopAllRunCommands(timeout: 2) { completed = true }
  XCTAssertTrue(completed, "no runStates entries to iterate → completes synchronously")
}

// MARK: Background run, status outcomes, run toast (issue #67)

func testStartRunsInBackgroundWithoutStealingFocus() {
  let store = makeStore([project("/a", workrooms: ["main"])])
  store.setRunConfig(RunConfig(command: "echo hi", autoRun: false), forProject: "/a")
  let t = target(store, "/a", "main")
  store.selectedTargetID = .workroom(project: "/a", name: "main")

