3302	  /// project reappears if it still exists) and surface the error. For `.fromDisk`, once the CLI
3303	  /// returns the config is already dropped — a subsequent Trash failure leaves the project removed
3304	  /// and is reported on its own (we do NOT restore it), listing the dirs left behind.
3305	  func deleteProject(_ project: Project, scope: DeleteProjectScope) {
3306	    let targetIDs = removeProjectLocally(project)
3307	    let stores = affectedStores
3308	    // Clear the project's targets (root + each workroom) from every OTHER window's split + selection
3309	    // too — `removeProjectLocally` only cleaned up this window (issue #70, OV #7).
3310	    let sids =
3311	      [SidebarID.root(project: project.path)]
3312	      + project.workrooms.map { SidebarID.workroom(project: project.path, name: $0.name) }
3313	    for store in stores where store !== self {
3314	      for sid in sids { store.detachTarget(sid) }
3315	    }
3316	
3317	    // ALWAYS stop runs in every window BEFORE any disk teardown so no dev server holds a deleted dir
3318	    // (issue #7/#70), then reap each target in every window, then run the CLI teardown once.
3319	    stopRunsAcrossWindows(targetIDs, stores: stores) { [weak self] in
3320	      guard let self else { return }
3321	      for store in stores { for id in targetIDs { store.reapTargetLocally(id) } }
3322	      Task {
3323	        let log =
3324	          scope == .configOnly
3325	          ? nil : ScriptLogSession(title: "Deleting \(project.displayName)", phase: "teardown")
3326	        do {
3327	          let trashPaths = try await self.cli.deleteProject(
3328	            project.path,
3329	            withWorkrooms: scope == .workrooms,
3330	            fromDisk: scope == .fromDisk
3331	          ) { text in DispatchQueue.main.async { log?.append(text) } }
3332	          if scope == .fromDisk {
3333	            // CLI already ran teardowns + dropped config; move the returned dirs to the Bin.
3334	            let failed = self.trashToBin(trashPaths)
3335	            if !failed.isEmpty { self.presentTrashFailure(project, failedPaths: failed) }
3336	          }
3337	        } catch {
3338	          await self.reload()
3339	          self.presentDeleteProjectFailure(project, error: error, log: log)
3340	        }
3341	      }
3342	    }
3343	  }
3344	
3345	  /// Moves each path to the Bin via the injected `trasher`, returning the URLs that could NOT be
3346	  /// moved so the caller can tell the user exactly what was left behind. The project is already
3347	  /// out of config by this point (the CLI dropped it), so a partial failure does not restore it.
3348	  /// Internal (not private) so the from-disk trash orchestration is unit-testable with a fake.
3349	  func trashToBin(_ urls: [URL]) -> [URL] {
3350	    var failed: [URL] = []
3351	    for url in urls {
3352	      do { try trasher.trash(url) } catch { failed.append(url) }
3353	    }
3354	    return failed
3355	  }
3356	
3357	  /// A from-disk delete dropped the project from config but some directories could not be moved to
3358	  /// the Bin. Report which ones so the user can move them manually (they are not lost).
3359	  func presentTrashFailure(_ project: Project, failedPaths: [URL]) {
3360	    let list = failedPaths.map(\.path).joined(separator: "\n")
3361	    errorTitle = "Some files of ‘\(project.displayName)’ could not be moved to the Bin"
3362	    errorMessage =
3363	      "‘\(project.displayName)’ was removed from Workroom, but these could not be moved to the "
3364	      + "Bin — move them manually:\n\(list)"
3365	  }
3366	
3367	  /// Optimistic, synchronous removal of a project from every piece of in-memory state — the
3368	  /// sidebar model, selection (project + target), the workroom split, and statuses. Returns
3369	  /// every `TerminalTarget.ID` the project owns (its root + each workroom) so the caller can
3370	  /// reap them once runs have stopped. Pure model mutation: NO CLI, disk, or config access, so
3371	  /// it is safe to unit-test directly. An in-flight status sweep is already guarded
3372	  /// (`targetExists` checks `projects`), so dropping the project here also stops a slow probe
3373	  /// from repopulating these entries.
3374	  @discardableResult
3375	  func removeProjectLocally(_ project: Project) -> [TerminalTarget.ID] {
3376	    let targetIDs =
3377	      [TerminalTarget.rootID(project: project.path)]
3378	      + project.workrooms.map { TerminalTarget.workroomID(project: project.path, name: $0.name) }
3379	
3380	    projects.removeAll { $0.id == project.id }
3381	    if selectedProjectID == project.id { selectedProjectID = nil }
3382	    // Clear selection if it pointed anywhere inside this project (its root or any workroom).
3383	    if let sel = selectedTargetID, sel.belongsToProject(project.path) { selectedTargetID = nil }
3384	    removeWorkroomSplitMember(.root(project: project.path))
3385	    workroomStatuses[.root(project: project.path)] = nil
3386	    setResolvedBranchName(nil, for: .root(project: project.path))
3387	    for w in project.workrooms {
3388	      removeWorkroomSplitMember(.workroom(project: project.path, name: w.name))
3389	      workroomStatuses[.workroom(project: project.path, name: w.name)] = nil
3390	      setResolvedBranchName(nil, for: .workroom(project: project.path, name: w.name))

